      "train_std_title": "Standaardprotocol: Ononderbroken ademen",
      "train_std_p1": "In het klassieke HRV-biofeedbackprotocol worden de sessies van 20 minuten uitgevoerd als continue ademhaling zonder tussenpauzes (bij voorkeur 2× daags).",
      "train_std_p2": "Continue resonantieopbouw: Het baroreflex-systeem heeft 1 tot 3 minuten onafgebroken ademen op de doelfrequentie nodig om in 0° fasesynchronie te raken en maximale RSA te bereiken. Om de 2 minuten pauzeren verbreekt dit proces.",
      "train_std_badge": "20 MIN CONTINU",
      "train_shallow_title": "Cruciaal: Voorkomen van hyperventilatie",
      "train_shallow_p1": "Bij het vertragen naar 4,5–6,5 ademhalingen/min ontstaat vaak de neiging om te diep adem te halen, waardoor te veel CO₂ wordt uitgeademd (hypocapnie).",
      "train_shallow_p2": "Belangrijkste instructie: adem oppervlakkig en ontspannen. Geen diepe yoga-ademhaling. Houd het minuutvolume gelijk aan rustige rustademhaling.",
      "train_shallow_badge": "OPPERVLAKKIG & ONTSPANNEN",
      "train_pause_title": "Wanneer pauzes nuttig zijn",
      "train_pause_p1": "Bij duizeligheid, lichtheid in het hoofd of benauwdheid:",
      "train_pause_step1": "1. Korte stop: Pauzeer 30 tot 60 seconden en adem normaal totdat het gevoel normaliseert.",
      "train_pause_step2": "2. Verminder volume: Adem bij hervatting bewuster oppervlakkig.",
      "train_pause_step3": "3. Bouw pauzes af: Start zo nodig met 2×10 minuten en werk toe naar 20 minuten aaneengesloten.",
      "train_pause_badge": "PRAKTIJK-AANPASSING",
      "safety_title": "Fysiologische veiligheid & klinische disclaimer",
      "safety_sub": "Risico's, contra-indicaties en richtlijnen voor resonantie-ademhaling en pursed-lips breathing",
      "safety_intro": "Resonantie-ademhaling en de lippenrem zijn veilige methoden, maar kennen fysiologische risico's bij onjuiste uitvoering of bepaalde aandoeningen.",
      "safety_sec1_title": "1. Risico's van geleide ademhaling & resonantie",
      "safety_sec1_a_title": "A. Hyperventilatie en hypocapnie (Belangrijkste risico)",
      "safety_sec1_a_mech": "Mechanisme: Te diep inademen bij lage ademfrequenties.",
      "safety_sec1_a_phys": "Gevolg: CO₂ daalt onder 3,5 %, wat cerebrale vaatvernauwing veroorzaakt.",
      "safety_sec1_a_symp": "Symptomen: Duizeligheid, tintelingen in handen en lippen, angstgevoelens.",
      "safety_sec1_a_counter": "Tegenmaatregel: Adem direct oppervlakkiger en rustiger.",
      "safety_sec1_b_title": "B. Paradoxale stress ('Te hard je best doen')",
      "safety_sec1_b_text": "Spanning in nek en gezicht activeert het sympathische zenuwstelsel en vermindert HRV.",
      "safety_sec1_c_title": "C. Drukpieken door adem inhouden (Valsalva-effect)",
      "safety_sec1_c_text": "Adem vasthouden verhoogt de intrathoracale druk en verstoort de veneuze terugstroom. Adem continu door.",
      "safety_sec1_d_title": "D. Specifieke contra-indicaties",
      "safety_sec1_d_acid": "Metabole acidose: Vertragen van ademhaling houdt CO₂ vast en verergert verzuring levensbedreigend.",
      "safety_sec1_d_pace": "Pacemaker: Vaste hartstimulatie verhindert natuurlijke RSA-resonantie.",
      "safety_sec1_d_hypo": "Ernstige orthostatische hypotensie: Kan bij rechtop zitten flauwvallen uitlokken.",
      "safety_sec2_title": "2. Fouten en risico's bij de lippenrem (Pursed-Lips)",
      "safety_sec2_forced": "Geforceerd uitademen: Actief persen met buikspieren beknelt de vena cava en veroorzaakt duizeligheid. Uitademen moet passief zijn.",
      "safety_sec2_trapping": "Air trapping: Te kleine lippenopening veroorzaakt luchtophoping in longblaasjes bij COPD.",
      "safety_sec2_tension": "Kaak- en nekspanning: Lippen klemmen leidt tot spierspanning in de schouders.",
      "safety_sec2_baro": "Barotraumarisico: Gecontra-indiceerd bij pneumothorax of longemfyseem.",
      "safety_rules_title": "Samenvatting: 4 vuistregels voor veilige beoefening",
      "safety_rule_1_title": "1. Blijf oppervlakkig en rustig",
      "safety_rule_1_desc": "Vul je longen niet maximaal; behoud een normaal rustvolume.",
      "safety_rule_2_title": "2. Uitademen zonder druk",
      "safety_rule_2_desc": "Tuit je lippen minimaal en laat de lucht passief ontsnappen.",
      "safety_rule_3_title": "3. Vloeiende ademhaling zonder stops",
      "safety_rule_3_desc": "Adem gelijkmatig in en uit zonder adempauzes bij het keren.",
      "safety_rule_4_title": "4. Duizeligheid is je waarschuwingssignaal",
      "safety_rule_4_desc": "Adem bij duizeligheid meteen oppervlakkiger om CO₂ te herstellen.",
      "science_title": "Why Resonance Breathing?",
      "science_sub": "Your cardiovascular system possesses an intrinsic resonance frequency governed by the baroreflex loop. One generic cadence does not fit all bodies.",
      "science_card1_title": "0° Phase Synchrony",
      "science_card1_desc": "When breathing at your resonant cadence (~0.1 Hz / 4.5–6.5 BPM), inhalation-driven tachycardia and exhalation-driven bradycardia align in exact synchrony, dramatically amplifying vagal tone.",
      "science_card2_title": "Anatomical Anchor (Hasuo 2023)",
      "science_card2_desc": "Vascular transit delay correlates directly with arterial length. Peak Frequency auto-calculates your personalized starting anchor using your height and biological sex from your Garmin user profile.",
      "science_card3_title": "Baroreflex Gain Amplification",
      "science_card3_desc": "Empirical research by Dr. Paul Lehrer demonstrates that resonance pacing stimulates the baroreceptors at their natural oscillation frequency, training autonomic flexibility and recovery.",
      "proto_title": "The Lehrer 2-Round Calibration Protocol",
      "proto_sub": "How Peak Frequency systematically discovers your precise physiological resonance cadence in under 12 minutes.",
      "proto_step0_title": "Rest Baseline",
      "proto_step0_desc": "2 minutes of spontaneous natural breathing. Establishes baseline resting heart rate and baseline HRV metrics without guidance.",
      "proto_step1_title": "Round 1: Coarse Scan",
      "proto_step1_desc": "Tests 3 cadences (Center, +0.25 BPM, -0.25 BPM) with 1-minute settling and 2-minute recording legs to detect peak HRV delta.",
      "proto_step2_title": "Round 2: Fine Tuning",
      "proto_step2_desc": "Narrows around Round 1's winning frequency with micro-increments of ±0.125 BPM to isolate your definitive resonance peak.",
      "proto_step3_title": "Resonance Lock",
      "proto_step3_desc": "The optimal cadence locks permanently into watch memory for daily 40/60 resonance training, accompanied by live synchrony graphs.",
      "feat_title": "Engineered for Performance & Privacy",
      "feat_sub": "Built specifically for Garmin AMOLED and MIP displays with a distraction-free experience.",
      "feat_somatic_title": "Minimal Somatic Prompts",
      "feat_somatic_desc": "Replaces distracting medical jargon with instant physical cues: 'Belly out', 'Pursed lips', 'Relax jaw', 'Without force'.",
      "feat_motion_title": "3D Motion Detection",
      "feat_motion_desc": "Onboard accelerometer filters wrist tremor while catching fidgeting. Displays a subtle 'Stay still' prompt without disrupting timing or HRV recording.",
      "feat_amoled_title": "AMOLED Low-Power Mode",
      "feat_amoled_desc": "Intelligent 3-second keep-alive refresh and sleep mode prevents display burn-in on Forerunner 965 and Venu/Vivoactive without dropping breath tracking.",
      "feat_lang_title": "14 European Languages",
      "feat_lang_desc": "Full native translations in English, German, Spanish, French, Italian, Dutch, Polish, Portuguese, Swedish, Danish, Norwegian, Finnish, Czech, and Hungarian.",
      "feat_privacy_title": "100% Private & Offline",
      "feat_privacy_desc": "Zero internet permissions (Communications). All biofeedback runs strictly in volatile RAM. No servers, no tracking, no ads.",
      "feat_fit_title": "Native FIT & RR Intervals",
      "feat_fit_desc": "Exports standard Garmin activities with high-precision beat-to-beat (rr_interval) developer fields compatible with Runalyze and Kubios.",
      "store_title": "Garmin Connect IQ Store Descriptions",
      "store_sub": "Ready-to-use copy formatted for the Garmin Connect IQ developer submission portal.",
